import React,{useMemo,useState,useRef} from 'react';
import {AlertTriangle,ArrowRight,BarChart3,Building2,CheckCircle2,ChevronDown,CircleCheck,ClipboardList,Coins,Leaf,LogOut,MapPin,Package,Plus,Recycle,Search,ShoppingBag,ShoppingCart,Sparkles,Star,Truck,UserRound,Users,Wallet,Wrench,Zap} from 'lucide-react';
import {Navigate,useLocation,useNavigate} from 'react-router-dom';
import {useAuth} from './auth/AuthContext';
import OrganizationMatchesPage from './OrganizationMatchesPage';
import {DELIVERY_STATES,LISTING_TYPES,ROLE_CONFIG,getRatingSummary,loadDemoData,matchListings,saveDemoData} from './data/demoStore';
import {analyzeComponentCondition} from './services/circuitTraceService';
import ProjectMakerBuilder from './project-maker/ProjectMakerBuilder';
import {getAvailableMarketplaceInventory,sameMarketplaceComponent} from './project-maker/services/marketplaceAdapter';
import './workspace.css';

const ROLE_NAV={
 project_maker:[['dashboard','Dashboard','/dashboard',BarChart3],['projects','My Projects','/projects',Wrench],['find-components','Find Components','/find-components',Search],['requirements','My Requirements','/requirements',ClipboardList],['requests','Requests','/requests',Package],['orders','Orders','/orders',ShoppingBag],['delivery','Delivery','/delivery',Truck],['feedback','Feedback','/feedback',Star],['impact','Savings & Impact','/impact',Leaf],['profile','Profile','/profile',UserRound]],
 seller:[['dashboard','Dashboard','/dashboard',BarChart3],['inventory','My Inventory','/inventory',Package],['listings','My Listings','/listings',ShoppingBag],['add-component','Add Component','/add-component',Plus],['requests','Requests','/requests',ClipboardList],['orders','Orders','/orders',ShoppingCart],['delivery','Delivery','/delivery',Truck],['payments','Payments','/payments',Wallet],['feedback','Feedback','/feedback',Star],['impact','My Impact','/impact',Leaf],['profile','Profile','/profile',UserRound]],
 organization:[['dashboard','Dashboard','/dashboard',BarChart3],['resources','Resources','/resources',Package],['listings','Listings','/listings',ShoppingBag],['project-requests','Project Requests','/project-requests',ClipboardList],['matches','Matches','/matches',Sparkles],['users','Users','/users',Users],['orders','Orders','/orders',ShoppingCart],['delivery','Delivery','/delivery',Truck],['analytics','Analytics','/analytics',BarChart3],['impact','Impact','/impact',Leaf],['profile','Profile','/profile',UserRound]]
};
const NEW_PRICES={'ESP32 DevKit':590,'SG90 Servo':120,'Arduino Uno':650,'LDR Sensor':35,'RFID RC522':180,'0.96 OLED':170,'MPU6050':210,'18650 Battery':140,'Raspberry Pi 3':2200};
const WEIGHT_GRAMS={'ESP32 DevKit':35,'SG90 Servo':9,'Arduino Uno':25,'LDR Sensor':2,'RFID RC522':12,'0.96 OLED':8,'MPU6050':4,'18650 Battery':45,'Raspberry Pi 3':45};
const DELIVERY_NEXT={ACCEPTED:'PACKED',PACKED:'PICKED_UP',PICKED_UP:'IN_TRANSIT',IN_TRANSIT:'DELIVERED'};
const titleCase=value=>value.toLowerCase().replace(/(^|_)([a-z])/g,(_,space,char)=>`${space?' ':''}${char.toUpperCase()}`);
const money=value=>`₹${Math.round(value).toLocaleString('en-IN')}`;
const pathTitle=value=>value.split('-').map(part=>part[0]?.toUpperCase()+part.slice(1)).join(' ');
const createId=prefix=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;

function estimatedNewCost(requirements){return requirements.reduce((sum,item)=>sum+(NEW_PRICES[item.name]??250)*item.quantity,0)}
function allAvailable(data){return data.listings.filter(listing=>listing.status==='AVAILABLE'&&listing.available_quantity>0)}
function activeListingQuantity(data,inventoryId){return data.listings.filter(item=>item.inventory_id===inventoryId&&!['CANCELLED','SOLD','TRANSFERRED'].includes(item.status)).reduce((sum,item)=>sum+item.available_quantity+item.reserved_quantity,0)}
function formatQty(value){return Number(value??0).toLocaleString('en-IN')}

function useMarketplaceData(){
 const [data,setData]=useState(loadDemoData);
 function update(change){setData(current=>saveDemoData(typeof change==='function'?change(current):change))}
 return [data,update];
}

function Stat({icon:Icon,value,label,detail}){return <div className="stat"><div className="statIcon"><Icon size={19}/></div><div><strong>{value}</strong><span>{label}</span>{detail&&<small>{detail}</small>}</div></div>}
function SectionTitle({eyebrow,title,description,action}){return <div className="workspaceSectionTitle"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>}
function EmptyState({title,description,action}){return <div className="emptyState"><div className="emptyStateIcon"><Recycle size={23}/></div><h3>{title}</h3><p>{description}</p>{action}</div>}
function DemoBadge(){return <span className="demoDataBadge"><span/>DEMO DATA</span>}

export function WorkspaceApp(){
 const location=useLocation();
 const navigate=useNavigate();
 const {profile,user,signOut,updateProfile}=useAuth();
 const [data,updateData]=useMarketplaceData();
 const projectMakerInventory=useMemo(()=>getAvailableMarketplaceInventory(data.listings),[data.listings]);
 const [menuOpen,setMenuOpen]=useState(false);
 const [signingOut,setSigningOut]=useState(false);
 const [error,setError]=useState('');
 const role=profile?.role;
 const config=ROLE_CONFIG[role];
 const base=config?.base;
 if(!config)return <Navigate to="/roles" replace/>;
 const route=location.pathname.slice(base.length).replace(/^\/+|\/+$/g,'')||'dashboard';
 if(route==='dashboard'&&location.pathname===base)return <Navigate to={`${base}/dashboard`} replace/>;
 const navigation=role==='project_maker'?[ROLE_NAV[role][0],['builder','Project Builder','/builder',Sparkles],...ROLE_NAV[role].slice(1)]:ROLE_NAV[role];
 const currentNav=navigation.find(([key])=>key===route);
 const displayName=role==='organization'?(profile.organization_name||profile.full_name):profile.full_name;
 const initials=(displayName||'SL').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();
 const ownInventory=data.inventories.filter(item=>item.owner_id===profile.id);
 const ownListings=data.listings.filter(item=>item.owner_id===profile.id);
 const ownProjects=data.projects.filter(item=>item.owner_id===profile.id);
 const ownRequests=data.requests.filter(item=>role==='project_maker'?item.maker_id===profile.id:item.seller_id===profile.id);
 const completedRequests=data.requests.filter(item=>item.status==='TRANSFERRED'&&(role==='project_maker'?item.maker_id===profile.id:item.seller_id===profile.id));
 const requestsForRole=role==='project_maker'?data.requests.filter(item=>item.maker_id===profile.id):data.requests.filter(item=>item.seller_id===profile.id);
 const activeOwnedQuantity=ownListings.filter(item=>!['CANCELLED','SOLD','TRANSFERRED'].includes(item.status)).reduce((sum,item)=>sum+item.available_quantity+item.reserved_quantity,0);
 const inventoryOwned=ownInventory.reduce((sum,item)=>sum+item.owned_quantity,0);
 const availableOwned=ownListings.reduce((sum,item)=>sum+item.available_quantity,0);
 const transferredOwned=ownListings.reduce((sum,item)=>sum+item.transferred_quantity,0);
 const donations=ownListings.filter(item=>item.listing_type==='DONATE').reduce((sum,item)=>sum+item.transferred_quantity,0);
 const sales=ownListings.filter(item=>item.listing_type==='SELL').reduce((sum,item)=>sum+item.transferred_quantity,0);
 const revenue=ownListings.filter(item=>item.listing_type==='SELL').reduce((sum,item)=>sum+item.transferred_quantity*item.price_per_unit,0);
 const impactComponents=completedRequests.reduce((sum,request)=>sum+request.quantity,0);
 const impactWaste=completedRequests.reduce((sum,request)=>sum+(WEIGHT_GRAMS[request.component_name]??20)*request.quantity,0);
 const impactSavings=completedRequests.reduce((sum,request)=>{
  const listing=data.listings.find(item=>item.id===request.listing_id);
  if(!listing)return sum;
  return sum+Math.max(0,(NEW_PRICES[request.component_name]??250)-listing.price_per_unit)*request.quantity;
 },0);
 const available=allAvailable(data);
 const routeTo=next=>navigate(`${base}${next==='/dashboard'?'/dashboard':next}`);
 const goProfile=()=>navigate(`${base}/profile`);
 async function logout(){
  setSigningOut(true);
  await signOut();
  setSigningOut(false);
  navigate('/roles',{replace:true});
 }
 function addInventory({componentName,category,quantity,condition,location:stockLocation}){
  updateData(current=>({...current,inventories:[...current.inventories,{id:createId('inventory'),owner_id:profile.id,component_name:componentName.trim(),category,owned_quantity:Number(quantity),condition,location:stockLocation.trim()||profile.location||'Not specified',demo:true}]}));
  routeTo(role==='organization'?'/resources':'/inventory');
 }
 function createListing({inventoryId,quantity,listingType,price,description,imageUrls}){
  const stock=ownInventory.find(item=>item.id===inventoryId);
  if(!stock){setError('Choose an inventory item first.');return false}
  const alreadyListed=activeListingQuantity(data,inventoryId);
  const qty=Number(quantity);
  if(!Number.isInteger(qty)||qty<1||qty>stock.owned_quantity-alreadyListed){setError(`Only ${Math.max(0,stock.owned_quantity-alreadyListed)} owned item(s) are still available to list.`);return false}
  const priceValue=listingType==='DONATE'?0:Number(price);
  if(listingType==='SELL'&&(!Number.isFinite(priceValue)||priceValue<=0)){setError('Enter a price greater than ₹0 for a sale listing.');return false}
  const nextListing={id:createId('listing'),inventory_id:stock.id,owner_id:profile.id,owner_type:role,owner_name:displayName,component_name:stock.component_name,category:stock.category,total_quantity:qty,available_quantity:qty,reserved_quantity:0,transferred_quantity:0,cancelled_quantity:0,condition:stock.condition,description:description.trim(),image_urls:imageUrls,location:profile.location||stock.location,distance_km:2.5,listing_type:listingType,price_per_unit:priceValue,status:'AVAILABLE',demo:true};
  updateData(current=>({...current,listings:[nextListing,...current.listings]}));
  setError('');
  routeTo('/listings');
  return true;
 }
 function createProject({name,description,budget,newBuildCost,location:projectLocation,requirements,category,difficulty,buildTime,wasteReduction,source}){
  const nextProject={id:createId('project'),owner_id:profile.id,owner_name:displayName,name:name.trim(),description:description.trim(),location:projectLocation.trim()||profile.location,budget:Number(budget),newBuildCost:Number(newBuildCost??budget),requirements,category,difficulty,buildTime,wasteReduction,source,demo:true};
  updateData(current=>({...current,projects:[nextProject,...current.projects]}));
  routeTo('/find-components');
 }
 function requestListing(listing,project,quantity){
  if(profile.role!=='project_maker'){setError('Organizations review maker requests from Project Requests.');return}
  const qty=Number(quantity);
  if(qty<1||qty>listing.available_quantity){setError('The available quantity changed. Choose a smaller quantity.');return}
  const duplicate=data.requests.some(request=>request.project_id===project.id&&request.listing_id===listing.id&&['REQUESTED','ACCEPTED'].includes(request.status));
  if(duplicate){setError('A request for this listing is already active.');return}
  const nextRequest={id:createId('request'),listing_id:listing.id,project_id:project.id,maker_id:profile.id,maker_name:displayName,seller_id:listing.owner_id,component_name:listing.component_name,quantity:qty,status:'REQUESTED',delivery_status:'REQUESTED',created_at:new Date().toISOString(),timeline:[{status:'REQUESTED',at:new Date().toISOString()}],demo:true};
  updateData(current=>({...current,requests:[nextRequest,...current.requests]}));
  setError('');
 }
 function respondToRequest(requestId,decision){
  const request=data.requests.find(item=>item.id===requestId);
  if(!request)return;
  const listing=data.listings.find(item=>item.id===request.listing_id);
  if(!listing)return;
  if(decision==='ACCEPTED'&&listing.available_quantity<request.quantity){setError('Not enough quantity remains available to accept this request.');return}
  updateData(current=>{
   const nextListings=current.listings.map(item=>{
    if(item.id!==listing.id)return item;
      if(decision==='ACCEPTED'&&item.available_quantity>=request.quantity)return {...item,available_quantity:item.available_quantity-request.quantity,reserved_quantity:item.reserved_quantity+request.quantity,status:item.available_quantity-request.quantity>0?'AVAILABLE':'RESERVED'};
    return item;
   });
   const now=new Date().toISOString();
  const nextRequests=current.requests.map(item=>item.id===requestId?{...item,status:decision,delivery_status:decision==='ACCEPTED'?'ACCEPTED':decision,timeline:[...(item.timeline??[]),{status:decision,at:now}]}:item);
   return {...current,listings:nextListings,requests:nextRequests};
  });
 }
 function cancelRequest(requestId){
  updateData(current=>{
   const request=current.requests.find(item=>item.id===requestId);
   const now=new Date().toISOString();
   const nextListings=current.listings.map(listing=>{
    if(listing.id!==request?.listing_id||request.status!=='ACCEPTED')return listing;
    return {...listing,available_quantity:listing.available_quantity+request.quantity,reserved_quantity:Math.max(0,listing.reserved_quantity-request.quantity),status:'AVAILABLE'};
   });
   const nextRequests=current.requests.map(item=>item.id===requestId?{...item,status:'CANCELLED',delivery_status:'CANCELLED',timeline:[...(item.timeline??[]),{status:'CANCELLED',at:now}]}:item);
   return {...current,listings:nextListings,requests:nextRequests};
  });
 }
 function advanceDelivery(requestId){
  updateData(current=>{
   const request=current.requests.find(item=>item.id===requestId);
   if(!request)return current;
   const nextStatus=DELIVERY_NEXT[request.delivery_status];
   if(!nextStatus)return current;
   const now=new Date().toISOString();
   const nextRequests=current.requests.map(item=>item.id===requestId?{...item,status:nextStatus==='DELIVERED'?'TRANSFERRED':'ACCEPTED',delivery_status:nextStatus,timeline:[...(item.timeline??[]),{status:nextStatus,at:now}]}:item);
  const deliveredListing=current.listings.find(item=>item.id===request.listing_id);
  const nextListings=current.listings.map(listing=>listing.id===request.listing_id&&nextStatus==='DELIVERED'?{...listing,reserved_quantity:Math.max(0,listing.reserved_quantity-request.quantity),transferred_quantity:listing.transferred_quantity+request.quantity,status:listing.available_quantity>0?'AVAILABLE':listing.reserved_quantity-request.quantity>0?'RESERVED':'TRANSFERRED'}:listing);
  const nextInventory=nextStatus==='DELIVERED'?current.inventories.map(item=>item.id===deliveredListing?.inventory_id?{...item,owned_quantity:Math.max(0,item.owned_quantity-request.quantity)}:item):current.inventories;
   return {...current,listings:nextListings,requests:nextRequests,inventories:nextInventory};
  });
 }

 const orgCompletedRequests=data.requests.filter(item=>item.seller_id===profile.id&&item.status==='TRANSFERRED');
 const orgProjectIds=new Set(orgCompletedRequests.map(item=>item.project_id));
 const orgImpactData={...data,profiles:[profile],listings:ownListings,projects:data.projects.filter(item=>orgProjectIds.has(item.id)),requests:orgCompletedRequests};
 const pageProps={role,profile,data,updateData,ownInventory,ownListings,ownProjects,ownRequests,requestsForRole,available,inventoryOwned,activeOwnedQuantity,availableOwned,transferredOwned,donations,sales,revenue,impactComponents,impactWaste,impactSavings,routeTo,addInventory,createListing,createProject,requestListing,respondToRequest,cancelRequest,advanceDelivery,setError,error,updateProfile};
 const page=<>
  {route==='dashboard'&&<DashboardPage {...pageProps}/>}
  {(route==='projects'||route==='requirements')&&role==='project_maker'&&<ProjectsPage {...pageProps}/>}
  {route==='builder'&&role==='project_maker'&&<ProjectMakerBuilder profile={profile} sharedInventory={projectMakerInventory} createProject={createProject}/>}
  {route==='find-components'&&role==='project_maker'&&<MatchingPage {...pageProps}/>}
  {route==='matches'&&role==='organization'&&<OrganizationMatchesPage profile={profile} data={data} routeTo={routeTo}/>}
  {(['inventory','resources'].includes(route))&&role!=='project_maker'&&<InventoryPage {...pageProps}/>}
  {route==='listings'&&role!=='project_maker'&&<ListingsPage {...pageProps}/>}
  {route==='add-component'&&role==='seller'&&<AddInventoryPage {...pageProps}/>}
  {(['requests','project-requests'].includes(route))&&<RequestsPage {...pageProps}/>}
  {(['orders','delivery'].includes(route))&&<DeliveryPage {...pageProps}/>}
  {route==='payments'&&role==='seller'&&<PaymentsPage {...pageProps}/>}
  {(['impact','analytics'].includes(route))&&<ImpactPage {...pageProps} data={role==='organization'?orgImpactData:data}/>}
  {route==='feedback'&&<FeedbackPage {...pageProps}/>}
  {route==='users'&&role==='organization'&&<UsersPage {...pageProps}/>}
  {route==='profile'&&<ProfilePage {...pageProps}/>}
  {!currentNav&&route!=='dashboard'&&<Navigate to={`${base}/dashboard`} replace/>}
 </>;

 return <div className="app workspaceApp">
  <aside className="sidebar"><div className="brand"><div className="brandmark"><Recycle size={22}/></div><div><b>SecondLife</b><span>{ROLE_CONFIG[role].title}</span></div></div><div className="nav">{navigation.map(([key,label,path,Icon])=><button key={key} className={route===key?'active':''} onClick={()=>routeTo(path)}><Icon size={18}/><span>{label}</span></button>)}</div><div className="sidebarBottom"><div className="role"><UserRound size={17}/><div><small>Signed in as</small><strong>{ROLE_CONFIG[role].singular}</strong></div></div><DemoBadge/></div></aside>
  <main className="main workspaceMain"><header><div><div className="eyebrow">CIRCULAR ELECTRONICS PLATFORM <span className="headerDot">·</span> {ROLE_CONFIG[role].title}</div><h1>{route==='dashboard'?dashboardHeading(role):currentNav?.[1]??pathTitle(route)}</h1></div><div className="workspaceHeaderActions"><DemoBadge/><div className="profileControl"><button className="profile" aria-haspopup="menu" aria-expanded={menuOpen} onClick={()=>setMenuOpen(!menuOpen)}>{profile.avatar_url?<img src={profile.avatar_url} alt=""/>:<span>{initials}</span>}{displayName}<ChevronDown size={15}/></button>{menuOpen&&<div className="profileMenu" role="menu"><span className="profileEmail">DEMO PROFILE · {ROLE_CONFIG[role].title}</span><button role="menuitem" onClick={goProfile}>Profile settings</button><button role="menuitem" onClick={logout} disabled={signingOut}><LogOut size={15}/>{signingOut?'Signing out...':'Sign out'}</button></div>}</div></div></header>{page}</main>
 </div>;
}

function dashboardHeading(role){return role==='project_maker'?'Build more. Waste less.':role==='seller'?'Make useful parts available.':'Put shared resources to work.'}

function DashboardPage(props){
 const {role,profile,data,ownProjects,ownListings,ownInventory,requestsForRole,inventoryOwned,activeOwnedQuantity,availableOwned,transferredOwned,donations,sales,revenue,impactComponents,impactWaste,impactSavings,routeTo}=props;
 if(role==='project_maker'){
  const projects=ownProjects;
  const needed=projects.reduce((sum,project)=>sum+project.requirements.reduce((total,item)=>total+item.quantity,0),0);
  const matched=data.listings.filter(item=>item.status==='AVAILABLE'&&item.available_quantity>0).length;
  const primary=projects[0];
  return <section className="workspacePage"><div className="dashboardHero roleMakerHero"><div><span className="pill"><Sparkles size={14}/> DEMO MARKETPLACE</span><h2>Build more.<br/><em>Waste less.</em></h2><p>Discover actual available components from local sellers and organizations, then track every request through delivery.</p><button className="primary" onClick={()=>routeTo('/find-components')}>Find Reusable Components <ArrowRight size={18}/></button></div><div className="dashboardOrbit"><div className="orbit o1"/><div className="orbit o2"/><div className="core"><Recycle size={48}/><span>REUSE</span></div><span className="orbitChip orbitChipOne">ESP32</span><span className="orbitChip orbitChipTwo">RFID</span><span className="orbitChip orbitChipThree">OLED</span></div></div>
   <div className="stats roleStats"><Stat icon={Wrench} value={projects.length} label="Active projects"/><Stat icon={Package} value={needed} label="Components needed"/><Stat icon={Search} value={matched} label="Matching listings"/><Stat icon={Coins} value={money(impactSavings)} label="Potential savings" detail="Completed reuse"/><Stat icon={Leaf} value={`${impactWaste} g`} label="E-waste reused" detail="Estimated from delivered items"/></div>
   <div className="grid2 workspaceGrid"><div className="panel"><div className="panelHead"><div><h3>My projects</h3><p>{projects.length} project{projects.length===1?'':'s'} in your workspace</p></div><button className="textBtn" onClick={()=>routeTo('/projects')}>View projects <ArrowRight size={15}/></button></div>{projects.slice(0,3).map(project=><ProjectRow project={project} key={project.id} onFind={()=>routeTo('/find-components')}/>)}{!projects.length&&<EmptyState title="Start with a project" description="Describe what you want to build and we’ll match it to available listings." action={<button className="primary small" onClick={()=>routeTo('/projects')}>Create project <Plus size={16}/></button>}/>}</div><div className="panel"><div className="panelHead"><div><h3>Request activity</h3><p>Latest component requests</p></div><button className="textBtn" onClick={()=>routeTo('/requests')}>View requests <ArrowRight size={15}/></button></div>{requestsForRole.slice(0,4).map(request=><RequestRow request={request} key={request.id} data={data}/>)}{!requestsForRole.length&&<EmptyState title="No requests yet" description="Matches from seller and organization listings will appear here." action={<button className="secondary" onClick={()=>routeTo('/find-components')}>Browse available listings</button>}/>}</div></div>
   {primary&&<div className="workspaceFootnote"><CircleCheck size={16}/> Last opened project: <strong>{primary.name}</strong><button onClick={()=>routeTo('/find-components')}>Find components</button></div>}
  </section>;
 }
 if(role==='seller')return <section className="workspacePage"><SectionTitle eyebrow="SELLER WORKSPACE" title="Your inventory, your choice." description="Only explicitly listed quantities are offered for reuse. Owned stock remains private until you publish a listing." action={<button className="primary small" onClick={()=>routeTo('/add-component')}><Plus size={16}/> Add component</button>}/><div className="stats roleStats"><Stat icon={Package} value={formatQty(inventoryOwned)} label="Components owned"/><Stat icon={ShoppingBag} value={formatQty(ownListings.reduce((sum,item)=>sum+item.total_quantity,0))} label="Components listed"/><Stat icon={CheckCircle2} value={formatQty(availableOwned)} label="Available for reuse"/><Stat icon={Recycle} value={formatQty(transferredOwned)} label="Successfully reused"/><Stat icon={Coins} value={money(revenue)} label="Demo revenue" detail={`${sales} sold · ${donations} donated`}/></div><div className="grid2 workspaceGrid"><div className="panel"><div className="panelHead"><div><h3>Inventory vs listings</h3><p>Owned does not automatically mean available</p></div><button className="textBtn" onClick={()=>routeTo('/inventory')}>Open inventory <ArrowRight size={15}/></button></div>{ownInventory.slice(0,5).map(item=><InventoryRow item={item} listed={activeListingQuantity(data,item.id)} key={item.id}/>)}{!ownInventory.length&&<EmptyState title="Add owned components" description="Start with your inventory. You decide separately what quantity to list." action={<button className="primary small" onClick={()=>routeTo('/add-component')}>Add to inventory <Plus size={16}/></button>}/>}</div><div className="panel"><div className="panelHead"><div><h3>Incoming requests</h3><p>Only accepted requests reserve stock</p></div><button className="textBtn" onClick={()=>routeTo('/requests')}>Manage <ArrowRight size={15}/></button></div>{requestsForRole.filter(item=>item.status==='REQUESTED'||item.status==='ACCEPTED').slice(0,4).map(request=><RequestRow request={request} key={request.id} data={data}/>)}{!requestsForRole.some(item=>item.status==='REQUESTED'||item.status==='ACCEPTED')&&<EmptyState title="No active requests" description="New project-maker requests will appear here."/>}</div></div></section>;
 const organizationListings=ownListings;
 const orgAvailable=organizationListings.reduce((sum,item)=>sum+item.available_quantity,0);
 const orgTransferred=organizationListings.reduce((sum,item)=>sum+item.transferred_quantity,0);
 const supportedProjects=new Set(data.requests.filter(item=>item.seller_id===profile.id&&item.status==='TRANSFERRED').map(item=>item.project_id)).size;
 return <section className="workspacePage"><SectionTitle eyebrow="ORGANIZATION WORKSPACE" title="Coordinate resources at scale." description="Manage bulk resources, publish deliberate listings, and track project reuse. Environmental values are estimates." action={<button className="primary small" onClick={()=>routeTo('/resources')}><Plus size={16}/> Add resources</button>}/><div className="stats roleStats"><Stat icon={Package} value={formatQty(orgAvailable)} label="Resources available"/><Stat icon={Recycle} value={formatQty(orgTransferred)} label="Resources reused"/><Stat icon={Wrench} value={supportedProjects} label="Projects supported"/><Stat icon={Users} value={new Set(data.requests.filter(item=>item.seller_id===profile.id&&item.status==='TRANSFERRED').map(item=>item.maker_id)).size} label="Project Makers helped"/><Stat icon={Leaf} value={`${impactWaste} g`} label="Estimated e-waste diverted"/></div><div className="grid2 workspaceGrid"><div className="panel"><div className="panelHead"><div><h3>Bulk resource listings</h3><p>Available, reserved, and transferred quantities</p></div><button className="textBtn" onClick={()=>routeTo('/listings')}>All listings <ArrowRight size={15}/></button></div>{organizationListings.slice(0,5).map(listing=><ListingRow listing={listing} data={data} key={listing.id}/>)}{!organizationListings.length&&<EmptyState title="Add organization resources" description="Record owned stock first, then publish only the quantity available for reuse." action={<button className="primary small" onClick={()=>routeTo('/resources')}>Add bulk resources <Plus size={16}/></button>}/>}</div><div className="panel"><div className="panelHead"><div><h3>Project requests</h3><p>Organization-owned resources requested by makers</p></div><button className="textBtn" onClick={()=>routeTo('/project-requests')}>Review <ArrowRight size={15}/></button></div>{requestsForRole.slice(0,4).map(request=><RequestRow request={request} key={request.id} data={data}/>)}{!requestsForRole.length&&<EmptyState title="No project requests yet" description="New requests for your published resources will appear here."/>}</div></div></section>;
}

function ProjectRow({project,onFind}){return <div className="workspaceRow"><div className="rowIcon"><Wrench size={17}/></div><div className="rowGrow"><strong>{project.name}</strong><small>{project.requirements.reduce((sum,item)=>sum+item.quantity,0)} components · Budget {money(project.budget)}</small></div><button className="textBtn" onClick={onFind}>Find matches <ArrowRight size={14}/></button></div>}
function InventoryRow({item,listed}){return <div className="workspaceRow"><div className="rowIcon"><Package size={17}/></div><div className="rowGrow"><strong>{item.component_name}</strong><small>Owned {item.owned_quantity} · Listed {listed} · Keep for myself {Math.max(0,item.owned_quantity-listed)}</small></div><span className="condition">{item.condition}</span></div>}
function ListingRow({listing,data}){const rating=data?getRatingSummary(data.feedback,listing.owner_id):null;return <div className="workspaceRow">{listing.image_urls?.[0]?<img className="listingThumb" src={listing.image_urls[0]} alt=""/>:<div className="rowIcon"><Package size={17}/></div>}<div className="rowGrow"><strong>{listing.component_name}</strong><small>{listing.listing_type} · {listing.condition} · {listing.location}{rating&&<> · ★ {rating.average.toFixed(1)} ({rating.count})</>}</small></div><div className="quantityStack"><strong>{formatQty(listing.available_quantity)} available</strong><small>{formatQty(listing.reserved_quantity)} reserved · {formatQty(listing.transferred_quantity)} transferred · {formatQty(listing.cancelled_quantity)} cancelled</small></div></div>}
function RequestRow({request,data}){const listing=data.listings.find(item=>item.id===request.listing_id);return <div className="workspaceRow"><div className="rowIcon"><ClipboardList size={17}/></div><div className="rowGrow"><strong>{request.component_name} ×{request.quantity}</strong><small>{request.maker_name||listing?.owner_name||'Marketplace user'} · {request.delivery_status||request.status}</small></div><StatusPill value={request.status}/></div>}
function StatusPill({value}){return <span className={`statusPill status-${(value||'available').toLowerCase()}`}>{(value||'AVAILABLE').replaceAll('_',' ')}</span>}

function ProjectsPage({ownProjects,profile,createProject,routeTo}){
 const [name,setName]=useState('');const [description,setDescription]=useState('');const [budget,setBudget]=useState('500');const [location,setLocation]=useState(profile.location||'');const [requirements,setRequirements]=useState('ESP32 DevKit x1\nRFID RC522 x1\nSG90 Servo x1\n0.96 OLED x1');const [error,setError]=useState('');
 function submit(event){event.preventDefault();setError('');const parsed=requirements.split(/\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const match=line.match(/^(.*?)\s*[x×]\s*(\d+)$/i);return match?{name:match[1].trim(),quantity:Number(match[2])}:null});if(!name.trim()){setError('Enter a project name.');return}if(!parsed.length||parsed.some(item=>!item)){setError('Add requirements using “Component name x quantity”, one per line.');return}createProject({name,description,budget,location,requirements:parsed})}
 return <section className="workspacePage"><SectionTitle eyebrow="PROJECT MAKER WORKSPACE" title="My Projects" description="Describe a build, set the budget, then search real demo listings from sellers and organizations." action={<DemoBadge/>}/><div className="projectCreation panel"><h3>Create a project</h3><form className="workspaceForm" onSubmit={submit}><label>Project name<input value={name} onChange={event=>setName(event.target.value)} placeholder="Smart Security System" required/></label><label className="formWide">Project description<textarea value={description} onChange={event=>setDescription(event.target.value)} placeholder="What are you building?" rows="2"/></label><label>Budget (₹)<input type="number" min="0" value={budget} onChange={event=>setBudget(event.target.value)} required/></label><label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="City"/></label><label className="formWide">Required components<textarea value={requirements} onChange={event=>setRequirements(event.target.value)} rows="5"/><small>One per line, formatted as component name x quantity.</small></label>{error&&<p className="inlineError formWide" role="alert">{error}</p>}<div className="formWide"><button className="primary" type="submit">Find Reusable Components <ArrowRight size={17}/></button></div></form></div><div className="projectListHeader"><h3>Saved projects</h3><span>{ownProjects.length} total</span></div><div className="projectList">{ownProjects.map(project=><article className="projectWorkspaceCard" key={project.id}><div className="projectCardTop"><span className="statusPill status-available">PROJECT</span><strong>{money(project.budget)} budget</strong></div><h3>{project.name}</h3><p>{project.description||'No description provided.'}</p><div className="projectRequirements">{project.requirements.map(requirement=><span key={requirement.name}>{requirement.name} ×{requirement.quantity}</span>)}</div><button className="secondary" onClick={()=>routeTo('/find-components')}>Find components <ArrowRight size={15}/></button></article>)}{!ownProjects.length&&<EmptyState title="No saved projects yet" description="Use the form above to add your first project and component requirements."/>}</div></section>
}

function MatchingPage({role,profile,data,ownProjects:makerProjects,requestListing,setError,error,routeTo}){
 const ownProjects=role==='organization'?data.projects:makerProjects;
 const matchProjects=ownProjects;
 const [projectId,setProjectId]=useState(matchProjects[0]?.id??'');const [quantities,setQuantities]=useState({});
 const project=matchProjects.find(item=>item.id===projectId);
 const matches=project?matchListings(project,data.listings.map(listing=>{const rating=getRatingSummary(data.feedback,listing.owner_id);return {...listing,owner_name:rating?`${listing.owner_name} · ★ ${rating.average.toFixed(1)} (${rating.count})`:listing.owner_name}}),profile.location||project.location||''):[];
 const newCost=project?(project.newBuildCost??estimatedNewCost(project.requirements)):0;
  const allocation=project?.requirements.map(requirement=>{
  let remaining=requirement.quantity;let cost=0;
  for(const option of matches.filter(item=>sameMarketplaceComponent(item.component_name,requirement.name)).sort((left,right)=>left.price_per_unit-right.price_per_unit)){
   const amount=Math.min(remaining,option.available_quantity);cost+=amount*option.price_per_unit;remaining-=amount;if(!remaining)break;
  }
  return {name:requirement.name,covered:remaining===0,cost};
 }) ?? [];
 const reusableTotal=allocation.reduce((sum,item)=>sum+item.cost,0);
 const covered=new Set(allocation.filter(item=>item.covered).map(item=>item.name.toLowerCase()));
 const componentCount=project?.requirements.reduce((sum,item)=>sum+item.quantity,0)??0;
 const coverage=project&&componentCount?Math.round(project.requirements.reduce((sum,item)=>sum+Math.min(item.quantity,matches.filter(match=>sameMarketplaceComponent(match.component_name,item.name)).reduce((qty,match)=>qty+match.available_quantity,0)),0)/componentCount*100):0;
  return <section className="workspacePage"><SectionTitle eyebrow="AVAILABLE MARKETPLACE LISTINGS" title="Find components for your build" description="Matches come only from seller and organization listings with currently available quantity." action={<DemoBadge/>}/>{!ownProjects.length?<EmptyState title="Create a project first" description="Project requirements drive listing matches and feasibility." action={<LinkButton to="/projects" label="Create project"/>}/>:<><div className="matchControls"><label>Project<select value={projectId} onChange={event=>setProjectId(event.target.value)}>{ownProjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="matchBudget"><span>Project budget</span><strong>{money(project.budget??0)}</strong></div></div>{project&&<div className="feasibilityStrip"><div><span>PROJECT FEASIBILITY</span><strong>{coverage}%</strong></div><div><b>{covered.size}/{project.requirements.length}</b><span>component types matched</span></div><div><b>{money(reusableTotal)}</b><span>current matched-listing cost</span></div><div><b>{money(Math.max(0,newCost-reusableTotal))}</b><span>potential saving vs new</span></div></div>}<div className="matchCardList">{matches.map(listing=>{
  const requested=data.requests.some(request=>request.project_id===project.id&&request.listing_id===listing.id&&['REQUESTED','ACCEPTED'].includes(request.status));
  const quantity=Number(quantities[listing.id]??Math.min(listing.needed,listing.available_quantity));
  const newPrice=NEW_PRICES[listing.component_name]??250;
  const scoreRows=[['Availability',`${listing.score_breakdown.availability}/40`],['Compatibility',`${listing.score_breakdown.compatibility}/20`],['Quantity',`${listing.score_breakdown.quantity}/20`],['Distance',`${listing.score_breakdown.distance}/10`],['Price',`${listing.score_breakdown.price}/10`]];
  return <article className="marketListingCard" key={listing.id}><div className="marketListingHeader"><div><div className="marketListingName"><h3>{listing.component_name}</h3><span className="matchScore"><Sparkles size={14}/>{listing.match_score}% match</span></div><p>{listing.description}</p></div><div className="marketPrice">{listing.listing_type==='DONATE'?<strong>DONATE</strong>:<strong>{money(listing.price_per_unit)}<small> / unit</small></strong>}<span>{listing.available_quantity} available</span></div></div><div className="listingMeta"><span><Building2 size={14}/>{listing.owner_name}</span><span><MapPin size={14}/>{listing.location} · {listing.distance_km} km</span><span><CheckCircle2 size={14}/>{listing.condition}</span><StatusPill value={listing.status}/></div><div className="matchingReason">Recommended: exact component requirement, {listing.available_quantity>=listing.needed?'full quantity available':'partial quantity available'}, and {listing.listing_type==='DONATE'?'no component cost':`${money(listing.price_per_unit)} per unit`}.</div><div className="scoreBreakdown">{scoreRows.map(([label,value])=><div key={label}><span>{label}</span><b>{value}</b></div>)}</div><div className="reuseCompare"><div><span>REUSED OPTION</span><strong>{listing.listing_type==='DONATE'?'₹0':money(listing.price_per_unit*quantity)}</strong><small>{listing.condition} · {listing.owner_name}</small></div><div><span>NEW OPTION</span><strong>{money(newPrice*quantity)}</strong><small>Market estimate</small></div><div><span>POTENTIAL SAVING</span><strong>{money(Math.max(0,(newPrice-listing.price_per_unit)*quantity))}</strong><small>Estimated e-waste: {(WEIGHT_GRAMS[listing.component_name]??20)*quantity} g</small></div></div><div className="listingCardActions"><label>Request quantity<input type="number" min="1" max={listing.available_quantity} value={quantity} onChange={event=>setQuantities(current=>({...current,[listing.id]:event.target.value}))}/></label><button className="primary small" disabled={requested||quantity<1||quantity>listing.available_quantity} onClick={()=>requestListing(listing,project,quantity)}>{requested?'Request sent':'Request component'} <ArrowRight size={15}/></button></div></article>})}{!matches.length&&<EmptyState title="No matching active listings" description="No currently available seller or organization listings match these requirements. Try another project or check back later."/>}</div>{error&&<p className="inlineError" role="alert">{error}</p>}</>}</section>
}

function LinkButton({to,label}){const navigate=useNavigate();return <button className="primary small" onClick={()=>navigate(to)}>{label}<ArrowRight size={15}/></button>}

function InventoryPage({role,profile,data,ownInventory,ownListings,addInventory}){
 const [showForm,setShowForm]=useState(false);const [name,setName]=useState('');const [category,setCategory]=useState('Microcontroller');const [quantity,setQuantity]=useState(1);const [condition,setCondition]=useState('Good');const [location,setLocation]=useState(profile.location||'');const [error,setError]=useState('');
 const org=role==='organization';
 function submit(event){event.preventDefault();if(!name.trim()){setError('Enter a component or device name.');return}if(Number(quantity)<1){setError('Quantity must be at least one.');return}addInventory({componentName:name,category,quantity,condition,location});}
 return <section className="workspacePage"><SectionTitle eyebrow={org?'ORGANIZATION RESOURCES':'SELLER INVENTORY'} title={org?'Resources':'My Inventory'} description="Inventory is private owned stock. It becomes available only after you create a listing." action={<button className="primary small" onClick={()=>setShowForm(!showForm)}><Plus size={16}/>{org?'Add bulk resources':'Add component'}</button>}/>{showForm&&<div className="panel inlineFormPanel"><h3>{org?'Add bulk resources':'Add owned component'}</h3><form className="workspaceForm compactForm" onSubmit={submit}><label>Component/device name<input value={name} onChange={event=>setName(event.target.value)} placeholder="ESP32 DevKit" required/></label><label>Category<select value={category} onChange={event=>setCategory(event.target.value)}>{['Microcontroller','Sensor','Display','Module','Actuator','Power','Computer','Other'].map(item=><option key={item}>{item}</option>)}</select></label><label>Owned quantity<input type="number" min="1" value={quantity} onChange={event=>setQuantity(event.target.value)} required/></label><label>Condition<select value={condition} onChange={event=>setCondition(event.target.value)}>{['Excellent','Good','Fair','For parts'].map(item=><option key={item}>{item}</option>)}</select></label><label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="City"/></label>{error&&<p className="inlineError formWide" role="alert">{error}</p>}<div className="formWide"><button className="primary small" type="submit">Save to inventory <CheckCircle2 size={15}/></button></div></form></div>}<div className="inventorySummary"><strong>Owned stock is not listed stock.</strong><span>Listed totals show explicit sharing; private quantity is calculated after live reservations and transfers.</span></div><div className="panel inventoryTable"><div className="inventoryTableHead"><span>COMPONENT</span><span>OWNED NOW</span><span>LISTED AVAILABLE</span><span>RESERVED</span><span>KEEP PRIVATE</span><span/></div>{ownInventory.map(item=>{const listingRows=ownListings.filter(listing=>listing.inventory_id===item.id);const available=listingRows.reduce((sum,listing)=>sum+listing.available_quantity,0);const reserved=listingRows.reduce((sum,listing)=>sum+listing.reserved_quantity,0);const privateQty=Math.max(0,item.owned_quantity-available-reserved);return <div className="inventoryTableRow" key={item.id}><div><strong>{item.component_name}</strong><small>{item.category} · {item.condition} · {item.location}</small></div><b>{item.owned_quantity}</b><b>{available}</b><b>{reserved}</b><b>{privateQty}</b><button className="textBtn" onClick={()=>setShowForm(true)}>Add stock</button></div>})}{!ownInventory.length&&<EmptyState title="Inventory is empty" description="Add what you own first. Listing is a separate step."/>}</div><p className="workspaceDisclaimer">Transfers reduce owned inventory only after delivery is marked complete. Demo inventory is stored in this browser.</p></section>
}

const EMPTY_AI_RESULT={componentName:'',category:'',manufacturer:'',partNumber:'',packageType:'',condition:'Good',workabilityScore:0,confidence:0,description:'',suggestedUses:[],detectedDamage:[]};

function normaliseAiResult(raw={}){
 const workabilityScore=Number(raw.workabilityScore ?? raw.workability_score ?? 0);
 const confidence=Number(raw.confidence ?? raw.confidenceScore ?? 0);
 const fallbackCondition=workabilityScore>=80?'Good':workabilityScore>=60?'Fair':'For parts';
 const suggestedUses=Array.isArray(raw.suggestedUses)?raw.suggestedUses:Array.isArray(raw.suggested_uses)?raw.suggested_uses:['Reuse in a compatible prototype build'];
 const detectedDamage=Array.isArray(raw.detectedDamage)?raw.detectedDamage:Array.isArray(raw.detected_damage)?raw.detected_damage:['No major damage detected'];
 return {componentName:String(raw.componentName || raw.component_name || '').trim(),category:String(raw.category || 'Other').trim(),manufacturer:String(raw.manufacturer || 'Unknown manufacturer').trim(),partNumber:String(raw.partNumber || raw.partIdentifier || raw.part_number || 'N/A').trim(),packageType:String(raw.packageType || raw.package_type || 'Unknown package').trim(),condition:String(raw.condition || fallbackCondition).trim(),workabilityScore:Number.isFinite(workabilityScore)?Math.min(100,Math.max(0,workabilityScore)):0,confidence:Number.isFinite(confidence)?Math.min(100,Math.max(0,confidence)):0,description:String(raw.description || raw.physicalCondition || '').trim(),suggestedUses:suggestedUses.filter(Boolean).length?suggestedUses.filter(Boolean):['General reuse in a compatible project'],detectedDamage:detectedDamage.filter(Boolean).length?detectedDamage.filter(Boolean):['No obvious visual damage detected']};
}

function AddInventoryPage({profile,updateData,routeTo}){return <CircuitTraceAddInventoryForm profile={profile} updateData={updateData} routeTo={routeTo}/>}
function CircuitTraceAddInventoryForm({profile,updateData,routeTo}){const navigate=useNavigate();const videoRef=useRef(null);const [imageData,setImageData]=useState('');const [imageName,setImageName]=useState('');const [analysisState,setAnalysisState]=useState('idle');const [analysisError,setAnalysisError]=useState('');const [aiResult,setAiResult]=useState(EMPTY_AI_RESULT);const [quantity,setQuantity]=useState(1);const [listingType,setListingType]=useState('DONATE');const [price,setPrice]=useState('');const [condition,setCondition]=useState('Good');const [location,setLocation]=useState(profile.location||'');const [deliveryMethod,setDeliveryMethod]=useState('Pickup');const [description,setDescription]=useState('');const [cameraStream,setCameraStream]=useState(null);const [cameraOpen,setCameraOpen]=useState(false);function applyImage(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{setImageData(String(reader.result));setImageName(file.name||'component-image.jpg');setAnalysisState('idle');setAnalysisError('');setAiResult(EMPTY_AI_RESULT)};reader.readAsDataURL(file)}function handleUpload(event){const file=event.target.files?.[0];if(!file){return}if(!file.type.startsWith('image/')){setAnalysisError('Choose a valid image file to inspect.');return}applyImage(file)}async function openCamera(){try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});setCameraStream(stream);setCameraOpen(true);if(videoRef.current){videoRef.current.srcObject=stream;}}catch(error){setAnalysisError('Camera access is unavailable. Please upload a component image instead.');}}function closeCamera(){if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());setCameraStream(null)}setCameraOpen(false)}function capturePhoto(){if(!videoRef.current)return;const canvas=document.createElement('canvas');canvas.width=videoRef.current.videoWidth||640;canvas.height=videoRef.current.videoHeight||480;const context=canvas.getContext('2d');context.drawImage(videoRef.current,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL('image/jpeg');closeCamera();setImageData(dataUrl);setImageName('camera-capture.jpg');setAnalysisState('idle');setAnalysisError('');setAiResult(EMPTY_AI_RESULT)}async function runCircuitTraceAnalysis(){if(!imageData){setAnalysisError('Upload a component photo before running CircuitTrace AI.');return}setAnalysisState('analyzing');setAnalysisError('');const result=await analyzeComponentCondition(imageData,imageData.match(/^data:([^;,]+)/)?.[1]||'image/jpeg');if(!result.success){setAnalysisState('failed');setAnalysisError(result.error||'CircuitTrace AI could not analyze the image.');return}const nextAiResult=normaliseAiResult(result.data);setAiResult(nextAiResult);setCondition(nextAiResult.condition||'Good');setAnalysisState('ready');if(nextAiResult.confidence<60){setAnalysisError('The image confidence is low. Please review the AI result and correct it before listing.')}}function updateAiField(field,value){setAiResult(current=>({...current,[field]:value}))}function submit(event){event.preventDefault();if(!imageData){setAnalysisError('Upload a component image before saving.');return}const name=aiResult.componentName.trim();if(!name){setAnalysisError('Enter a component name before saving.');return}if(Number(quantity)<1){setAnalysisError('Quantity must be at least one.');return}if(listingType==='SELL'&&(!price||Number(price)<=0)){setAnalysisError('Enter a valid price for the sale listing.');return}const safeLocation=(location||profile.location||'Not specified').trim();const nextInventory={id:createId('inventory'),owner_id:profile.id,component_name:name,category:aiResult.category||'Other',owned_quantity:Number(quantity),condition:condition||'Good',location:safeLocation,demo:true,aiAnalysis:{analyzed:true,componentName:aiResult.componentName,category:aiResult.category,manufacturer:aiResult.manufacturer,partNumber:aiResult.partNumber,packageType:aiResult.packageType,condition:aiResult.condition,workabilityScore:aiResult.workabilityScore,confidence:aiResult.confidence,detectedDamage:aiResult.detectedDamage,suggestedUses:aiResult.suggestedUses,description:aiResult.description}};const nextListing={id:createId('listing'),inventory_id:nextInventory.id,owner_id:profile.id,owner_type:'seller',owner_name:profile.full_name||'Seller',component_name:name,category:nextInventory.category,total_quantity:Number(quantity),available_quantity:Number(quantity),reserved_quantity:0,transferred_quantity:0,cancelled_quantity:0,condition:condition||aiResult.condition||'Good',description:(description||aiResult.description||'').trim()||'Component added using CircuitTrace AI review.',image_urls:[imageData],location:safeLocation,distance_km:2.5,listing_type:listingType,price_per_unit:listingType==='SELL'?Number(price):0,status:'AVAILABLE',demo:true,delivery_method:deliveryMethod,aiAnalysis:nextInventory.aiAnalysis};updateData(current=>({...current,inventories:[nextInventory,...current.inventories],listings:[nextListing,...current.listings]}));
 setAnalysisError('');
 navigate('/seller/listings',{replace:true})
}return <section className="workspacePage"><SectionTitle eyebrow="SELLER AI INSPECTION" title="Add component to inventory" description="Upload a component image, review the CircuitTrace AI result, then confirm the listing details before publishing." action={<DemoBadge/>}/><div className="panel inventoryFormPanel"><div className="aiUploadGrid"><div className="aiUploadCard"><h3>1. Upload component</h3><div className="aiUploadActions"><label className="primary small fileButton">Upload image<input type="file" accept="image/*" onChange={handleUpload} hidden/></label><button type="button" className="secondary small" onClick={openCamera}>Use camera</button></div>{imageData&&analysisState==='idle'&&<button type="button" className="primary small" onClick={runCircuitTraceAnalysis}><Sparkles size={15}/>Analyze with CircuitTrace AI</button>}
{imageName&&<p className="listingFormNote">Selected image: {imageName}</p>}</div>{(analysisState==='analyzing'||analysisState==='failed'||analysisState==='ready'||analysisState==='manual')&&<div className="aiUploadCard"><h3>2. CircuitTrace AI</h3>{analysisState==='analyzing'&&<div className="aiInspectionBanner"><span className="loadingSpinner"/>Analyzing image with Gemini...</div>}{analysisState==='failed'&&<div className="aiInspectionBanner failure"><AlertTriangle size={15}/>AI analysis failed. You can retry or enter the details manually.</div>}{analysisState==='ready'&&<div className="aiInspectionBanner success"><CheckCircle2 size={15}/>CircuitTrace AI result ready for review.</div>}{analysisState==='manual'&&<div className="aiInspectionBanner"><Sparkles size={15}/>Manual review mode enabled.</div>}{analysisError&&<p className="inlineError" role="alert">{analysisError}</p>}{(analysisState==='failed'||analysisState==='manual')&&<div className="buttonRow"><button type="button" className="primary small" onClick={runCircuitTraceAnalysis}>Try again</button><button type="button" className="secondary small" onClick={()=>{setAiResult(current=>({...EMPTY_AI_RESULT,...current,componentName:current.componentName||'',category:current.category||'',manufacturer:current.manufacturer||'',partNumber:current.partNumber||'',packageType:current.packageType||'',condition:current.condition||'Good'}));setAnalysisState('manual');setAnalysisError('');}}>Enter manually</button></div>}{analysisState==='ready'&&<div className="buttonRow"><button type="button" className="primary small" onClick={runCircuitTraceAnalysis}>Re-run analysis</button><button type="button" className="secondary small" onClick={()=>setAnalysisState('manual')}>Manual edit</button></div>}</div>}</div>{(analysisState==='ready'||analysisState==='manual')&&<form className="workspaceForm" onSubmit={submit}><div className="formWide"><h3>Review AI result</h3></div><label>Component name<input value={aiResult.componentName} onChange={event=>updateAiField('componentName',event.target.value)} placeholder="e.g. ESP32-WROOM-32"/></label><label>Category<select value={aiResult.category} onChange={event=>updateAiField('category',event.target.value)}>{['Microcontroller','Sensor','Display','Module','Actuator','Power','Computer','Passive','Connector','Other'].map(item=><option key={item}>{item}</option>)}</select></label><label>Manufacturer<input value={aiResult.manufacturer} onChange={event=>updateAiField('manufacturer',event.target.value)} placeholder="e.g. Espressif"/></label><label>Part number<input value={aiResult.partNumber} onChange={event=>updateAiField('partNumber',event.target.value)} placeholder="e.g. ESP32-WROOM-32"/></label><label>Package<input value={aiResult.packageType} onChange={event=>updateAiField('packageType',event.target.value)} placeholder="e.g. QFN"/></label><label>Condition<select value={aiResult.condition} onChange={event=>updateAiField('condition',event.target.value)}>{['Excellent','Good','Fair','For parts'].map(item=><option key={item}>{item}</option>)}</select></label><label>Workability score<input type="number" min="0" max="100" value={aiResult.workabilityScore} onChange={event=>updateAiField('workabilityScore',Number(event.target.value)||0)}/></label><label>Confidence<input type="number" min="0" max="100" value={aiResult.confidence} onChange={event=>updateAiField('confidence',Number(event.target.value)||0)}/></label><label className="formWide">Description<textarea rows="3" value={aiResult.description} onChange={event=>updateAiField('description',event.target.value)} placeholder="Describe the component condition and any visible damage."/></label><label className="formWide">Suggested uses<textarea rows="2" value={aiResult.suggestedUses.join(', ')} onChange={event=>updateAiField('suggestedUses',event.target.value.split(',').map(value=>value.trim()).filter(Boolean))} placeholder="Reuse in a sensor project, bench testing, prototyping"/></label><label className="formWide">Damage detected<textarea rows="2" value={aiResult.detectedDamage.join(', ')} onChange={event=>updateAiField('detectedDamage',event.target.value.split(',').map(value=>value.trim()).filter(Boolean))} placeholder="Burn marks, soot, cracked body, no visible damage"/></label><div className="formWide"><h3>Listing details</h3></div><label>Quantity<input type="number" min="1" value={quantity} onChange={event=>setQuantity(event.target.value)} required/></label><label>Sell or Donate<select value={listingType} onChange={event=>setListingType(event.target.value)}>{['DONATE','SELL'].map(item=><option key={item}>{item}</option>)}</select></label>{listingType==='SELL'&&<label>Price per unit (₹)<input type="number" min="1" value={price} onChange={event=>setPrice(event.target.value)} required/></label>}{listingType==='DONATE'&&<label>Pickup / Delivery<select value={deliveryMethod} onChange={event=>setDeliveryMethod(event.target.value)}>{['Pickup','Delivery'].map(item=><option key={item}>{item}</option>)}</select></label>}<label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="Chennai"/></label><label>Pickup / Delivery<select value={deliveryMethod} onChange={event=>setDeliveryMethod(event.target.value)}>{['Pickup','Delivery'].map(item=><option key={item}>{item}</option>)}</select></label><label className="formWide">Seller notes<textarea rows="2" value={description} onChange={event=>setDescription(event.target.value)} placeholder="Any pickup notes, included accessories, or condition details."/></label><div className="formWide aiPreviewSummary"><div><span>AI IDENTIFICATION</span><strong>{aiResult.componentName || 'Component name'}</strong><small>{aiResult.condition || 'Condition'} · Workability {aiResult.workabilityScore || 0}% · Confidence {aiResult.confidence || 0}%</small></div><div><span>LISTING</span><strong>{quantity} unit{Number(quantity)===1?'':'s'} · {listingType}</strong><small>{listingType==='SELL' ? `₹${Number(price || 0).toLocaleString('en-IN')} / unit` : 'Donation listing'} · {deliveryMethod} · {location||profile.location||'Location not specified'}</small></div></div>{analysisError&&<p className="inlineError formWide" role="alert">{analysisError}</p>}<div className="formWide"><button className="primary" type="submit">List component <ArrowRight size={16}/></button></div></form>}{cameraOpen&&<div className="cameraModal" aria-modal="true" role="dialog"><div className="cameraPanel"><div className="cameraHeader"><h3>Component camera</h3><button type="button" className="secondary small" onClick={closeCamera}>Close</button></div><video ref={videoRef} autoPlay playsInline muted/><div className="cameraFooter"><button type="button" className="primary small" onClick={capturePhoto}>Capture image</button></div></div></div>}</div><div className="inventorySummary"><Package size={18}/><span>Seller-owned inventory is saved to the existing SecondLife marketplace flow. Use the AI review fields to confirm the final record before publishing.</span></div></section>}
function AddInventoryForm({profile,addInventory}){const navigate=useNavigate();const [name,setName]=useState('');const [category,setCategory]=useState('Microcontroller');const [quantity,setQuantity]=useState(1);const [condition,setCondition]=useState('Good');const [location,setLocation]=useState(profile.location||'');const [error,setError]=useState('');function submit(event){event.preventDefault();if(!name.trim()){setError('Enter a component or device name.');return}addInventory({componentName:name,category,quantity,condition,location})}return <section className="workspacePage"><SectionTitle eyebrow="OWNERSHIP FIRST" title="Add component to inventory" description="This adds owned stock only. It does not publish anything to the marketplace."/><div className="panel inventoryFormPanel"><form className="workspaceForm" onSubmit={submit}><label>Component/device name<input value={name} onChange={event=>setName(event.target.value)} placeholder="ESP32 DevKit" required/></label><label>Category<select value={category} onChange={event=>setCategory(event.target.value)}>{['Microcontroller','Sensor','Display','Module','Actuator','Power','Computer','Other'].map(item=><option key={item}>{item}</option>)}</select></label><label>Owned quantity<input type="number" min="1" value={quantity} onChange={event=>setQuantity(event.target.value)} required/></label><label>Condition<select value={condition} onChange={event=>setCondition(event.target.value)}>{['Excellent','Good','Fair','For parts'].map(item=><option key={item}>{item}</option>)}</select></label><label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="City"/></label>{error&&<p className="inlineError formWide" role="alert">{error}</p>}<div className="formWide"><button className="primary" type="submit">Save owned inventory <ArrowRight size={16}/></button></div></form></div><div className="inventorySummary"><Package size={18}/><span>Owned inventory is private. To offer any quantity, create a separate listing after this step.</span></div><button className="textBtn" onClick={()=>navigate('/seller/inventory')}>Back to inventory</button></section>}

function ListingsPage({role,data,ownListings,ownInventory,createListing,setError,error,updateData}){
 const [showForm,setShowForm]=useState(false);const [inventoryId,setInventoryId]=useState(ownInventory[0]?.id??'');const [quantity,setQuantity]=useState(1);const [listingType,setListingType]=useState('DONATE');const [price,setPrice]=useState('');const [description,setDescription]=useState('');const [imagesText,setImagesText]=useState('');const isOrg=role==='organization';
 const inventory=ownInventory.find(item=>item.id===inventoryId);
 const listable=inventory?Math.max(0,inventory.owned_quantity-activeListingQuantity({listings:ownListings},inventory.id)):0;
 function submit(event){event.preventDefault();const imageUrls=imagesText.split(/[\n,]+/).map(value=>value.trim()).filter(Boolean);if(imageUrls.some(value=>{try{return !['http:','https:'].includes(new URL(value).protocol)}catch{return true}})){setError('Each image must use a valid http:// or https:// URL.');return}const ok=createListing({inventoryId,quantity,listingType,price,description,imageUrls});if(ok)setShowForm(false)}
 function cancel(listing){if(listing.reserved_quantity>0){setError('This listing has accepted requests. Resolve or deliver them before cancelling.');return}updateData(current=>({...current,listings:current.listings.map(item=>item.id===listing.id?{...item,status:'CANCELLED',available_quantity:0,cancelled_quantity:(item.cancelled_quantity??0)+item.available_quantity}:item)}));setError('')}
 return <section className="workspacePage"><SectionTitle eyebrow={isOrg?'ORGANIZATION LISTINGS':'SELLER LISTINGS'} title={isOrg?'Published resources':'My Listings'} description="Only published listing quantities can be found by project makers." action={<button className="primary small" onClick={()=>{setShowForm(!showForm);setError('')}}><Plus size={16}/>Create listing</button>}/>{showForm&&<div className="panel inlineFormPanel"><h3>Publish inventory for reuse</h3>{!ownInventory.length?<EmptyState title="No owned inventory" description="Add the item to inventory before publishing a listing." action={<LinkButton to={isOrg?'/organization/resources':'/seller/add-component'} label="Add owned stock"/>}/>:<form className="workspaceForm compactForm" onSubmit={submit}><label>Inventory item<select value={inventoryId} onChange={event=>setInventoryId(event.target.value)}>{ownInventory.map(item=><option key={item.id} value={item.id}>{item.component_name} · owned {item.owned_quantity}</option>)}</select><small>Unlisted owned quantity: {listable}</small></label><label>Quantity to list<input type="number" min="1" max={listable} value={quantity} onChange={event=>setQuantity(event.target.value)} required/></label><label>Listing type<select value={listingType} onChange={event=>{setListingType(event.target.value);if(event.target.value==='DONATE')setPrice('0')}}>{LISTING_TYPES.map(item=><option key={item}>{item}</option>)}</select></label>{listingType==='SELL'&&<label>Price per unit (₹)<input type="number" min="1" value={price} onChange={event=>setPrice(event.target.value)} required/></label>}<label className="formWide">Description<textarea rows="2" value={description} onChange={event=>setDescription(event.target.value)} placeholder="Condition details, included accessories, pickup notes"/></label><label className="formWide">Image URLs<textarea rows="2" value={imagesText} onChange={event=>setImagesText(event.target.value)} placeholder="https://example.com/component.jpg"/><small>Optional. Add one http(s) image URL per line.</small></label>{error&&<p className="inlineError formWide" role="alert">{error}</p>}<div className="formWide listingFormNote">DONATE listings are ₹0. SELL payments are simulated for this prototype; no payment is processed.</div><div className="formWide"><button className="primary small" type="submit">Publish listing <ArrowRight size={15}/></button></div></form>}</div>}{error&&!showForm&&<p className="inlineError" role="alert">{error}</p>}<div className="listingManagement">{ownListings.map(listing=><article className="managedListing" key={listing.id}><ListingRow listing={listing} data={data}/><div className="managedListingControls"><span>{listing.listing_type==='DONATE'?'₹0 donation':`${money(listing.price_per_unit)} per unit`} · total {listing.total_quantity}</span>{listing.status!=='CANCELLED'&&listing.available_quantity>0&&<button className="textBtn dangerText" onClick={()=>cancel(listing)}>Cancel available quantity</button>}</div></article>)}{!ownListings.length&&<EmptyState title="Nothing listed yet" description="Inventory stays private until you choose a quantity and publish it." action={<button className="primary small" onClick={()=>setShowForm(true)}>Create first listing <Plus size={16}/></button>}/>}</div></section>
}

function RequestsPage({role,data,requestsForRole,respondToRequest,cancelRequest}){
 const seller=role!=='project_maker';
 return <section className="workspacePage"><SectionTitle eyebrow={seller?'SELLER REQUESTS':'PROJECT MAKER REQUESTS'} title={seller?'Project requests':'My requests'} description="Requested stock remains available until accepted. Acceptance reserves quantity; delivery completion records transfer."/><div className="requestList">{requestsForRole.map(request=>{const listing=data.listings.find(item=>item.id===request.listing_id);const project=data.projects.find(item=>item.id===request.project_id);return <article className="requestCard" key={request.id}><div className="requestCardHeading"><div><span className="eyebrow">{seller?request.maker_name:listing?.owner_name}</span><h3>{request.component_name} × {request.quantity}</h3><p>{project?.name||'Marketplace project'} · {listing?.location||'Location not specified'}</p></div><StatusPill value={request.delivery_status||request.status}/></div><div className="requestStockLine"><span>Listing available: {listing?.available_quantity??0}</span><span>Reserved: {listing?.reserved_quantity??0}</span><span>Type: {listing?.listing_type??'N/A'}</span><span>Subtotal: {listing?.listing_type==='SELL'?money((listing.price_per_unit??0)*request.quantity):'₹0 donation'}</span></div><DeliveryTimeline request={request}/><div className="requestActions">{seller&&request.status==='REQUESTED'&&<><button className="primary small" onClick={()=>respondToRequest(request.id,'ACCEPTED')} disabled={(listing?.available_quantity??0)<request.quantity}>Accept and reserve</button><button className="secondary small" onClick={()=>respondToRequest(request.id,'REJECTED')}>Reject</button></>}{!seller&&['REQUESTED','ACCEPTED'].includes(request.status)&&<button className="secondary small" onClick={()=>cancelRequest(request.id)}>Cancel request</button>}{seller&&request.status==='ACCEPTED'&&<span className="listingFormNote">Use Delivery to advance this request.</span>}</div></article>})}{!requestsForRole.length&&<EmptyState title="No requests yet" description={seller?'Project-maker requests for your listings will appear here.':'Your listing requests and their status will appear here.'}/>}</div></section>
}

function DeliveryTimeline({request}){const current=request.delivery_status||request.status;const states=DELIVERY_STATES.filter(status=>status!=='REQUESTED'||request.timeline?.some(item=>item.status==='REQUESTED'));return <div className="deliveryTimeline">{states.map((status,index)=>{const reached=(request.timeline??[]).some(item=>item.status===status)||status===current;return <div className={`timelineStep ${reached?'reached':''} ${current===status?'current':''}`} key={status}><span>{reached?<CheckCircle2 size={15}/>:index+1}</span><small>{status.replaceAll('_',' ')}</small></div>})}</div>}

function DeliveryPage({role,data,requestsForRole,advanceDelivery}){const seller=role!=='project_maker';const rows=requestsForRole.filter(request=>request.status==='ACCEPTED'||request.status==='TRANSFERRED');return <section className="workspacePage"><SectionTitle eyebrow="DELIVERY TRACKING · DEMO" title="Delivery timeline" description="Demo state transitions are stored locally. No carrier or payment gateway is connected."/><div className="deliveryCards">{rows.map(request=>{const listing=data.listings.find(item=>item.id===request.listing_id);const next=DELIVERY_NEXT[request.delivery_status];return <article className="requestCard" key={request.id}><div className="requestCardHeading"><div><h3>{request.component_name} × {request.quantity}</h3><p>{request.maker_name} · {listing?.owner_name} · {listing?.location}</p></div><StatusPill value={request.delivery_status}/></div><DeliveryTimeline request={request}/><div className="requestStockLine"><span>{listing?.listing_type==='SELL'?`Demo subtotal ${money(listing.price_per_unit*request.quantity)}`:'₹0 donation'}</span><span>{request.status==='TRANSFERRED'?'Transfer recorded':'Reservation active'}</span></div>{seller&&next&&<button className="primary small" onClick={()=>advanceDelivery(request.id)}>Mark {next.replaceAll('_',' ').toLowerCase()} <ArrowRight size={15}/></button>}</article>})}{!rows.length&&<EmptyState title="No deliveries in progress" description="Accepted requests appear here with their delivery timeline."/>}</div></section>}

function PaymentsPage({revenue,ownListings}){return <section className="workspacePage"><SectionTitle eyebrow="DEMO PAYMENTS" title="Payments" description="No real payment processing is integrated. Values below are estimates based only on completed demo transfers."/><div className="stats"><Stat icon={Wallet} value={money(revenue)} label="Estimated seller revenue"/><Stat icon={ShoppingBag} value={ownListings.filter(item=>item.listing_type==='SELL').reduce((sum,item)=>sum+item.transferred_quantity,0)} label="Transferred sale units"/></div><div className="inventorySummary"><Coins size={18}/><span>Transactions are simulated. Do not treat these amounts as collected funds or payout records.</span></div></section>}

function ImpactPage({role,data,impactComponents,impactWaste,impactSavings,donations,sales,revenue}){let metrics=[];if(role==='project_maker')metrics=[['Money saved',money(impactSavings),Coins],['Components reused',formatQty(impactComponents),Recycle],['Estimated e-waste diverted',`${impactWaste} g`,Leaf]];else if(role==='seller')metrics=[['Components reused',formatQty(impactComponents),Recycle],['Items donated',formatQty(donations),Leaf],['Items sold',formatQty(sales),ShoppingBag],['Demo revenue',money(revenue),Wallet],['Estimated e-waste diverted',`${impactWaste} g`,Leaf]];else{const transfers=data.listings.filter(item=>item.owner_id===data.profiles.find(profile=>profile.organization_name===profile.organization_name)?.id).reduce((sum,item)=>sum+item.transferred_quantity,0);metrics=[['Resources reused',formatQty(transfers||impactComponents),Recycle],['Projects supported',formatQty(data.projects.length),Wrench],['Project Makers helped',formatQty(new Set(data.requests.filter(item=>item.status==='TRANSFERRED').map(item=>item.maker_id)).size),Users],['Estimated e-waste diverted',`${impactWaste} g`,Leaf],['Estimated savings',money(impactSavings),Coins]]}
 return <section className="workspacePage"><SectionTitle eyebrow="MEASURED AFTER TRANSFER" title={role==='project_maker'?'Savings & Impact':role==='seller'?'My Impact':'Organization Impact'} description="Environmental and savings figures are estimates and update only after a delivery is marked delivered and transferred."/><div className="stats impactRoleStats">{metrics.map(([label,value,Icon])=><Stat key={label} icon={Icon} value={value} label={label}/>)}</div><div className="inventorySummary"><Leaf size={18}/><span>Estimated e-waste values use component-weight assumptions. They are not measured environmental claims.</span></div></section>
}

function LegacyFeedbackPage({role,data,requestsForRole,updateData,profile}){const completed=requestsForRole.filter(item=>item.status==='TRANSFERRED');const [ratings,setRatings]=useState({});const [message,setMessage]=useState('');function rate(requestId,field,value){setRatings(current=>({...current,[requestId]:{...current[requestId],[field]:Number(value)}}))}function save(request){const feedback={id:createId('feedback'),request_id:request.id,author_id:profile.id,role,rating:ratings[request.id]??{},created_at:new Date().toISOString()};updateData(current=>({...current,feedback:[feedback,...current.feedback]}));
 setMessage('Feedback saved in demo data.')}return <section className="workspacePage"><SectionTitle eyebrow="TRANSACTION FEEDBACK" title="Feedback" description="Ratings are available after a completed transfer and stored in demo data."/>{completed.map(request=><article className="requestCard feedbackCard" key={request.id}><div><h3>{request.component_name} · {request.maker_name}</h3><p>Request completed {new Date(request.created_at).toLocaleDateString()}</p></div><div className="ratingFields">{(role==='project_maker'?['condition','listing accuracy','seller experience','overall experience']:['project maker','transaction','communication']).map(field=><label key={field}>{titleCase(field)}<select value={ratings[request.id]?.[field]??5} onChange={event=>rate(request.id,field,event.target.value)}>{[5,4,3,2,1].map(value=><option key={value} value={value}>{value} stars</option>)}</select></label>)}</div><button className="primary small" onClick={()=>save(request)}>Save feedback <Star size={14}/></button></article>)}{message&&<p className="successMessage" role="status">{message}</p>}{!completed.length&&<EmptyState title="Feedback opens after reuse" description="Complete a request delivery first; pending requests cannot receive transaction ratings."/>}</section>}

function FeedbackPage({role,data,requestsForRole,updateData,profile}){
 const completed=requestsForRole.filter(request=>request.status==='TRANSFERRED');
 const [ratings,setRatings]=useState({});
 const [message,setMessage]=useState('');
 const fields=role==='project_maker'?['condition','listing accuracy','seller experience','overall experience']:['project maker','transaction','communication'];
 function rate(requestId,field,value){setRatings(current=>({...current,[requestId]:{...current[requestId],[field]:Number(value)}}))}
 function save(request){
  const listing=data.listings.find(item=>item.id===request.listing_id);
  const feedback={id:createId('feedback'),request_id:request.id,author_id:profile.id,target_id:role==='project_maker'?listing?.owner_id:request.maker_id,role,rating:ratings[request.id]??{},created_at:new Date().toISOString()};
  updateData(current=>({...current,feedback:[feedback,...current.feedback]}));
  setMessage('Feedback saved in demo data.');
 }
 return <section className="workspacePage"><SectionTitle eyebrow="TRANSACTION FEEDBACK" title="Feedback" description="Rate the transaction after transfer. Average ratings appear on marketplace listings."/>{completed.map(request=><article className="requestCard feedbackCard" key={request.id}><div><h3>{request.component_name} · {request.maker_name}</h3><p>Request completed {new Date(request.created_at).toLocaleDateString()}</p></div><div className="ratingFields">{fields.map(field=><label key={field}>{titleCase(field)}<select value={ratings[request.id]?.[field]??5} onChange={event=>rate(request.id,field,event.target.value)}>{[5,4,3,2,1].map(value=><option key={value} value={value}>{value} stars</option>)}</select></label>)}</div><button className="primary small" onClick={()=>save(request)}>Save feedback <Star size={14}/></button></article>)}{message&&<p className="successMessage" role="status">{message}</p>}{!completed.length&&<EmptyState title="Feedback opens after reuse" description="Complete a request delivery first; pending requests cannot receive transaction ratings."/>}</section>
}

function UsersPage({data}){const profiles=data.profiles.filter(item=>item.role==='project_maker');return <section className="workspacePage"><SectionTitle eyebrow="COMMUNITY DIRECTORY · DEMO" title="Project Makers" description="Demo directory data for project collaboration. Contact actions are not connected to messaging."/><div className="directoryList">{profiles.map(person=><div className="workspaceRow" key={person.id}><div className="rowIcon"><UserRound size={17}/></div><div className="rowGrow"><strong>{person.full_name}</strong><small>PROJECT MAKER · {person.location}</small></div><span className="statusPill status-available">DEMO PROFILE</span></div>)}</div></section>}

function ProfilePage({role,profile,updateProfile}){const [name,setName]=useState(profile.full_name??'');const [organizationName,setOrganizationName]=useState(profile.organization_name??'');const [organizationType,setOrganizationType]=useState(profile.organization_type??'College');const [location,setLocation]=useState(profile.location??'');const [avatarUrl,setAvatarUrl]=useState(profile.avatar_url??'');const [message,setMessage]=useState('');const isOrg=role==='organization';function submit(event){event.preventDefault();updateProfile({full_name:name.trim()||(isOrg?organizationName.trim():''),organization_name:isOrg?organizationName.trim():null,organization_type:isOrg?organizationType:null,location:location.trim(),avatar_url:avatarUrl.trim()||null});setMessage('Demo profile updated.')}
 return <section className="workspacePage"><SectionTitle eyebrow={ROLE_CONFIG[role].title} title={isOrg?'Organization profile':'Profile'} description="Role is fixed for this demo identity. Use sign out and choose another role to test a different workspace."/><div className="panel profileWorkspacePanel"><form className="workspaceForm" onSubmit={submit}><label>Email<input type="email" value={profile.email??''} placeholder="No email in this demo profile" readOnly disabled/></label><label>{isOrg?'Organization name':'Full name'}<input value={isOrg?organizationName:name} onChange={event=>isOrg?setOrganizationName(event.target.value):setName(event.target.value)} required/></label>{isOrg&&<label>Contact person<input value={name} onChange={event=>setName(event.target.value)} required/></label>}{isOrg&&<label>Organization type<select value={organizationType} onChange={event=>setOrganizationType(event.target.value)}>{['College','University','NGO','Company','Recycling Organization','Government Organization','Other'].map(type=><option key={type}>{type}</option>)}</select></label>}<label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="City or region"/></label><label className="formWide">Avatar URL<input value={avatarUrl} onChange={event=>setAvatarUrl(event.target.value)} placeholder="https://example.com/avatar.jpg"/></label><div className="roleProfileSummary"><span>ACCOUNT TYPE</span><strong>{ROLE_CONFIG[role].title}</strong><span>DEMO PROFILE · SAVED LOCALLY</span></div>{message&&<p className="successMessage formWide" role="status">{message}</p>}<div className="formWide"><button className="primary" type="submit">Save profile <CheckCircle2 size={16}/></button></div></form></div></section>
}

function titleCaseRole(role){return ROLE_CONFIG[role]?.singular??'SecondLife member'}
